import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;
    static final long RING_SIZE = 100_000L;

    static long djb2Hash(String s) {
        long hash = 5381;
        for (int i = 0; i < s.length(); i++) {
            hash = ((hash * 33) + s.charAt(i)) % MOD;
        }
        hash ^= (hash >>> 15);
        hash = (hash * 2246822519L) & 0xFFFFFFFFL;
        hash ^= (hash >>> 13);
        hash = (hash * 3266489917L) & 0xFFFFFFFFL;
        hash ^= (hash >>> 16);
        return hash;
    }

    static TreeMap<Long, String> buildRing(String[] servers, int vnodesPerServer) {
        TreeMap<Long, String> ring = new TreeMap<>();
        for (String s : servers) {
            for (int v = 0; v < vnodesPerServer; v++) {
                ring.put(djb2Hash(s + "#" + v) % RING_SIZE, s);
            }
        }
        return ring;
    }

    static String getServer(String key, TreeMap<Long, String> ring) {
        long position = djb2Hash(key) % RING_SIZE;
        Map.Entry<Long, String> entry = ring.ceilingEntry(position);
        return entry != null ? entry.getValue() : ring.firstEntry().getValue();
    }

    static double stddev(Map<String, Integer> counts) {
        double mean = 0;
        for (int c : counts.values()) mean += c;
        mean /= counts.size();
        double variance = 0;
        for (int c : counts.values()) variance += (c - mean) * (c - mean);
        variance /= counts.size();
        return Math.sqrt(variance);
    }

    public static void main(String[] args) {
        String[] servers = {"A", "B", "C"};
        int numKeys = 3000;

        for (int vnodes : new int[]{1, 150}) {
            TreeMap<Long, String> ring = buildRing(servers, vnodes);
            Map<String, Integer> counts = new TreeMap<>();
            for (String s : servers) counts.put(s, 0);
            for (int i = 0; i < numKeys; i++) {
                String server = getServer("key" + i, ring);
                counts.put(server, counts.get(server) + 1);
            }
            System.out.println(vnodes + " virtual node(s) per server: " + counts + ", stddev=" + String.format("%.1f", stddev(counts)));
        }
    }
}

