import bisect


def djb2_hash(s):
    hash_value = 5381
    for ch in s:
        hash_value = ((hash_value * 33) + ord(ch)) % MOD
    hash_value ^= (hash_value >> 15)
    hash_value = (hash_value * 2246822519) & 0xFFFFFFFF
    hash_value ^= (hash_value >> 13)
    hash_value = (hash_value * 3266489917) & 0xFFFFFFFF
    hash_value ^= (hash_value >> 16)
    return hash_value


def build_ring(servers, vnodes_per_server):
    ring = {}
    for s in servers:
        for v in range(vnodes_per_server):
            ring[djb2_hash(f"{s}#{v}") % RING_SIZE] = s
    positions = sorted(ring.keys())
    return positions, ring


def get_server(key, positions, ring):
    position = djb2_hash(key) % RING_SIZE
    idx = bisect.bisect_left(positions, position)
    if idx == len(positions):
        idx = 0
    return ring[positions[idx]]


def stddev(counts):
    values = list(counts.values())
    mean = sum(values) / len(values)
    variance = sum((v - mean) ** 2 for v in values) / len(values)
    return variance ** 0.5


def main():
    servers = ["A", "B", "C"]
    num_keys = 3000

    for vnodes in (1, 150):
        positions, ring = build_ring(servers, vnodes)
        counts = {s: 0 for s in servers}
        for i in range(num_keys):
            server = get_server(f"key{i}", positions, ring)
            counts[server] += 1
        print(f"{vnodes} virtual node(s) per server: {counts}, stddev={stddev(counts):.1f}")


if __name__ == "__main__":
    main()

