#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <cmath>
#include <iomanip>
using namespace std;

const long long MOD = 1000000007LL;
const long long RING_SIZE = 100000LL;

long long djb2Hash(const string& s) {
    long long hash = 5381;
    for (char c : s) {
        hash = ((hash * 33) + static_cast<unsigned char>(c)) % MOD;
    }
    unsigned long long h = static_cast<unsigned long long>(hash);
    h ^= (h >> 15);
    h = (h * 2246822519ULL) & 0xFFFFFFFFULL;
    h ^= (h >> 13);
    h = (h * 3266489917ULL) & 0xFFFFFFFFULL;
    h ^= (h >> 16);
    return static_cast<long long>(h);
}

map<long long, string> buildRing(const vector<string>& servers, int vnodesPerServer) {
    map<long long, string> ring;
    for (const string& s : servers) {
        for (int v = 0; v < vnodesPerServer; v++) {
            ring[djb2Hash(s + "#" + to_string(v)) % RING_SIZE] = s;
        }
    }
    return ring;
}

string getServer(const string& key, map<long long, string>& ring) {
    long long position = djb2Hash(key) % RING_SIZE;
    auto it = ring.lower_bound(position);
    if (it == ring.end()) it = ring.begin();
    return it->second;
}

double stddev(map<string, int>& counts) {
    double mean = 0;
    for (auto& kv : counts) mean += kv.second;
    mean /= counts.size();
    double variance = 0;
    for (auto& kv : counts) variance += (kv.second - mean) * (kv.second - mean);
    variance /= counts.size();
    return sqrt(variance);
}

int main() {
    vector<string> servers = {"A", "B", "C"};
    int numKeys = 3000;

    for (int vnodes : {1, 150}) {
        auto ring = buildRing(servers, vnodes);
        map<string, int> counts;
        for (const string& s : servers) counts[s] = 0;
        for (int i = 0; i < numKeys; i++) {
            string server = getServer("key" + to_string(i), ring);
            counts[server]++;
        }
        cout << vnodes << " virtual node(s) per server: {";
        bool first = true;
        for (auto& kv : counts) {
            if (!first) cout << ", ";
            cout << kv.first << "=" << kv.second;
            first = false;
        }
        cout << "}, stddev=" << fixed << setprecision(1) << stddev(counts) << endl;
    }

    return 0;
}
